<?php
require_once __DIR__ . '/../backend/lib.php';
require_once __DIR__ . '/../public/db_connect.php';
require_login();  $user = current_user();
$station_id = user_station_id();
$product_id = (int)($_GET['product_id'] ?? 0);
$start_date = $_GET['start_date'] ?? date('Y-m-01');
$end_date = $_GET['end_date'] ?? date('Y-m-d');  // Fetch product information
$product = null;
if ($product_id > 0) {  $stmt = $pdo->prepare("  SELECT i.id, p.name as product_name, pt.name as type, i.stock_level as current_stock  FROM station_inventory i  JOIN products p ON i.product_id = p.id  JOIN product_types pt ON p.type_id = pt.id  WHERE i.station_id = ? AND i.id = ?  ");  $stmt->execute([$station_id, $product_id]);  $product = $stmt->fetch(PDO::FETCH_ASSOC);
}  if (!$product) {  die('<div class="empty-state"><i class="fas fa-exclamation-circle"></i><p>Product not found.</p></div>');
}  // Calculate inventory movements
$movements = [];  // Get sales (Out)
$stmt = $pdo->prepare("  SELECT DATE(s.sale_date) as date, si.quantity, si.total_amount, 'Sale' as movement_type,  c.name as customer_name, u.name as staff_name  FROM sales s  LEFT JOIN sale_items si ON s.id = si.sale_id  LEFT JOIN customers c ON s.customer_id = c.id  LEFT JOIN users u ON s.user_id = u.id  WHERE si.name = ? AND (s.station_id = ? OR s.station_id IS NULL)  AND s.sale_date BETWEEN ? AND ?  ORDER BY s.sale_date DESC
");
$stmt->execute([$product['product_name'], $station_id, $start_date, $end_date]);
$sales = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($sales as $sale) {  $movements[] = [  'date' => $sale['date'],  'type' => 'OUT',  'description' => 'Sale to ' . ($sale['customer_name'] ?? 'Walk-in'),  'quantity' => $sale['quantity'],  'reference' => $sale['staff_name'],  'amount' => $sale['total_amount']  ];
}  // Get deliveries (In)
if ($product['type'] === 'fuel') {  try {  $stmt = $pdo->prepare("  SELECT delivery_date as date, delivery_liters as quantity, 'Fuel Delivery' as movement_type,  supplier_name as reference, estimated_cost as amount  FROM fuel_deliveries  WHERE fuel_type = ? AND station_id = ? AND delivery_date BETWEEN ? AND ?  ORDER BY delivery_date DESC  ");  $stmt->execute([$product['product_name'], $station_id, $start_date, $end_date]);  $deliveries = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($deliveries as $delivery) {  $movements[] = [  'date' => $delivery['date'],  'type' => 'IN',  'description' => $delivery['movement_type'] . ' from ' . ($delivery['reference'] ?? 'Supplier'),  'quantity' => $delivery['quantity'],  'reference' => $delivery['reference'] ?? 'Supplier',  'amount' => $delivery['amount'] ?? 0  ];  }  } catch (Exception $e) {  // Table might not exist  }
} else {  try {  $stmt = $pdo->prepare("  SELECT DATE(po.updated_at) as date, poi.received_quantity as quantity,  'Purchase Order' as movement_type, po.supplier_name as reference,  (poi.received_quantity * poi.unit_cost) as amount  FROM purchase_order_items poi  JOIN purchase_orders po ON poi.po_id = po.id  WHERE poi.item_name = ? AND po.station_id = ?  AND po.updated_at BETWEEN ? AND ?  ORDER BY po.updated_at DESC  ");  $stmt->execute([$product['product_name'], $station_id, $start_date . ' 00:00:00', $end_date . ' 23:59:59']);  $deliveries = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($deliveries as $delivery) {  $movements[] = [  'date' => $delivery['date'],  'type' => 'IN',  'description' => $delivery['movement_type'] . ' from ' . ($delivery['reference'] ?? 'Supplier'),  'quantity' => $delivery['quantity'],  'reference' => $delivery['reference'] ?? 'Supplier',  'amount' => $delivery['amount'] ?? 0  ];  }  } catch (Exception $e) {  // Table might not exist  }
}  // Sort movements by date
usort($movements, function($a, $b) {  return strtotime($b['date']) - strtotime($a['date']);
});  // Calculate totals
$total_in = 0;
$total_out = 0;
$total_amount = 0;  foreach ($movements as $movement) {  if ($movement['type'] === 'IN') {  $total_in += $movement['quantity'];  } else {  $total_out += $movement['quantity'];  }  $total_amount += $movement['amount'];
}  // Calculate beginning stock (approximation)
$beginning_stock = $product['current_stock'] - $total_in + $total_out;
?>
<!DOCTYPE html>
<html>
<head>  <meta charset="UTF-8">  <meta name="viewport" content="width=device-width, initial-scale=1.0">  <title>Inventory History - <?php echo htmlspecialchars($product['product_name']); ?></title>  <link rel="stylesheet" href="../assets/vendor/fontawesome/css/all.min.css">  <style>  * { box-sizing: border-box; margin: 0; padding: 0; }  body {  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;  background: rgba(0,0,0,0.5);  min-height: 100vh;  display: flex;  align-items: center;  justify-content: center;  padding: 20px;  }  .modal-container {  background: white;  border-radius: 12px;  width: 100%;  max-width: 1000px;  max-height: 90vh;  box-shadow: 0 20px 60px rgba(0,0,0,0.3);  overflow: hidden;  display: flex;  flex-direction: column;  }  .modal-header {  background: linear-gradient(135deg, #2563eb, #1d4ed8);  color: white;  padding: 16px 24px;  display: flex;  justify-content: space-between;  align-items: center;  }  .modal-header h3 { font-size: 18px; font-weight: 600; }  .close-btn {  background: none;  border: none;  color: white;  font-size: 24px;  cursor: pointer;  opacity: 0.8;  }  .close-btn:hover { opacity: 1; }  .modal-body {  padding: 24px;  overflow-y: auto;  flex: 1;  }  .product-info {  background: #f8fafc;  border-radius: 8px;  padding: 16px;  margin-bottom: 20px;  display: flex;  justify-content: space-between;  align-items: center;  flex-wrap: wrap;  gap: 16px;  }  .product-details {  flex: 1;  }  .product-name {  font-size: 18px;  font-weight: 600;  color: #0f172a;  margin-bottom: 4px;  }  .product-meta {  font-size: 14px;  color: #64748b;  }  .stock-info {  text-align: right;  }  .stock-label {  font-size: 12px;  color: #64748b;  margin-bottom: 4px;  }  .stock-value {  font-size: 24px;  font-weight: 700;  color: #0f172a;  }  .summary-cards {  display: grid;  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));  gap: 16px;  margin-bottom: 24px;  }  .summary-card {  background: linear-gradient(135deg, #f8fafc, #e2e8f0);  border-radius: 8px;  padding: 16px;  text-align: center;  }  .summary-card.beginning { background: linear-gradient(135deg, #e0e7ff, #c7d2fe); }  .summary-card.in { background: linear-gradient(135deg, #dcfce7, #bbf7d0); }  .summary-card.out { background: linear-gradient(135deg, #fee2e2, #fecaca); }  .summary-card.current { background: linear-gradient(135deg, #dbeafe, #bfdbfe); }  .summary-label { font-size: 12px; color: #64748b; margin-bottom: 4px; }  .summary-value { font-size: 20px; font-weight: 700; color: #0f172a; }  .movements-table {  width: 100%;  border-collapse: collapse;  margin-top: 16px;  }  .movements-table th {  background: #f8fafc;  font-weight: 600;  font-size: 12px;  text-transform: uppercase;  padding: 12px 8px;  border-bottom: 2px solid #e2e8f0;  text-align: left;  }  .movements-table td {  padding: 10px 8px;  border-bottom: 1px solid #f1f5f9;  font-size: 13px;  }  .movements-table tr:hover td {  background-color: #f8fafc;  }  .movement-type {  padding: 2px 8px;  border-radius: 4px;  font-size: 11px;  font-weight: 600;  color: white;  }  .type-in { background: #10b981; }  .type-out { background: #ef4444; }  .empty-state {  text-align: center;  padding: 40px;  color: #64748b;  }  .empty-state i {  font-size: 48px;  color: #ef4444;  margin-bottom: 16px;  }  .modal-footer {  padding: 16px 24px;  border-top: 1px solid #e2e8f0;  text-align: right;  }  .btn {  padding: 10px 20px;  border-radius: 8px;  border: none;  cursor: pointer;  font-weight: 500;  font-size: 14px;  margin-left: 8px;  }  .btn-secondary { background: #f1f5f9; color: #64748b; }  .btn-secondary:hover { background: #e2e8f0; }  .btn-primary { background: #2563eb; color: white; }  .btn-primary:hover { background: #1d4ed8; }  </style>
</head>
<body>  <div class="modal-container">  <div class="modal-header">  <h3><i class="fas fa-boxes"></i> Inventory History - <?php echo htmlspecialchars($product['product_name']); ?></h3>  <button class="close-btn" onclick="window.close()">&times;</button>  </div>  <div class="modal-body">  <div class="product-info">  <div class="product-details">  <div class="product-name"><?php echo htmlspecialchars($product['product_name']); ?></div>  <div class="product-meta">  Category: <?php echo ucfirst($product['type']); ?> |  Period: <?php echo date('M d, Y', strtotime($start_date)); ?> - <?php echo date('M d, Y', strtotime($end_date)); ?>  </div>  </div>  <div class="stock-info">  <div class="stock-label">Current Stock</div>  <div class="stock-value"><?php echo number_format($product['current_stock'], 2); ?></div>  </div>  </div>  <div class="summary-cards">  <div class="summary-card beginning">  <div class="summary-label">Beginning Stock</div>  <div class="summary-value"><?php echo number_format($beginning_stock, 2); ?></div>  </div>  <div class="summary-card in">  <div class="summary-label">Stock In</div>  <div class="summary-value">+<?php echo number_format($total_in, 2); ?></div>  </div>  <div class="summary-card out">  <div class="summary-label">Stock Out</div>  <div class="summary-value">-<?php echo number_format($total_out, 2); ?></div>  </div>  <div class="summary-card current">  <div class="summary-label">Ending Stock</div>  <div class="summary-value"><?php echo number_format($product['current_stock'], 2); ?></div>  </div>  </div>  <?php if (!empty($movements)): ?>  <table class="movements-table">  <thead>  <tr>  <th>Date</th>  <th>Type</th>  <th>Description</th>  <th>Quantity</th>  <th>Reference</th>  <th>Amount</th>  </tr>  </thead>  <tbody>  <?php foreach ($movements as $movement): ?>  <tr>  <td><?php echo date('M d, Y', strtotime($movement['date'])); ?></td>  <td>  <span class="movement-type type-<?php echo strtolower($movement['type']); ?>">  <?php echo $movement['type']; ?>  </span>  </td>  <td><?php echo htmlspecialchars($movement['description']); ?></td>  <td>  <?php if ($movement['type'] === 'IN'): ?>  <span style="color: #10b981;">+</span>  <?php else: ?>  <span style="color: #ef4444;">-</span>  <?php endif; ?>  <?php echo number_format($movement['quantity'], 2); ?>  </td>  <td><?php echo htmlspecialchars($movement['reference']); ?></td>  <td>₱<?php echo number_format($movement['amount'], 2); ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  <?php else: ?>  <div class="empty-state">  <i class="fas fa-box-open"></i>  <p>No inventory movements found for this period.</p>  </div>  <?php endif; ?>  </div>  <div class="modal-footer">  <button class="btn btn-primary" onclick="printDetails()">  <i class="fas fa-print"></i> Print  </button>  <button class="btn btn-secondary" onclick="window.close()">Close</button>  </div>  </div>  <script>  function printDetails() {  window.print();  }  </script>
</body>
</html>
